import logging
from pathlib import Path

log = logging.getLogger('projectdocumentai')


def stored_path(upload_dir: Path, storage_key: str) -> Path:
    # Keys are generated by the server, never derived from the uploaded filename.
    return upload_dir / storage_key


def remove_stored_file(upload_dir: Path, storage_key: str) -> None:
    path = stored_path(upload_dir, storage_key)
    try:
        path.unlink(missing_ok=True)
    except OSError:
        # A failed cleanup must not turn a committed database deletion into a 500.
        log.warning('Could not remove stored document %s', storage_key)
        return
    try:
        path.parent.rmdir()
    except OSError:
        pass  # Other documents may still be in this project directory.
